# custctx: each rule of src/quest/combat/custctx.cpp and custctx_targets.h removed or bent once; src/quest/tests/custctx_test.cpp must fail on every
# one (the shared files it changed are each run against the test that covers them). Sourced by ../mutants.sh, which defines
# `runm <name> <file> <sed> [<build dir> <test target>]`.
F=src/quest/combat/custctx.cpp
T=src/quest/combat/custctx_targets.h
H=src/quest/combat/custctx.h
